{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  let d = [];

  try {
    // STEALTH
    await page.evaluateOnNewDocument(() => {
      Object.defineProperty(navigator, 'webdriver', { get: () => false });
      window.chrome = { runtime: {} };
    });
    await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');
    await page.setViewport({ width: 1280, height: 800 });

    // === LOGIN ===
    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'networkidle2', timeout: 60000 });
    await w(2000);
    d.push('LOGIN');

    const eInp = await page.$('#email_principal');
    if (eInp) { await eInp.click(); await w(300); await eInp.type(EMAIL, { delay: 30 }); }
    await w(1000);

    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Continuar com Email')); if(b) b.click(); });
    await w(3000);

    const pwd = await page.$('#pwdInput');
    if (pwd) { await pwd.click(); await w(300); await pwd.type(SENHA, { delay: 30 }); }
    await w(1000);
    d.push('SENHA');

    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Entrar'); if(b) b.click(); });
    await w(5000);
    d.push('ENTRAR');

    // HAPVIDA - clica na operadora
    await page.evaluate(() => {
      const img = document.querySelector('img[src*="hapvida"]');
      if (img) {
        const parent = img.closest('.clickable-element') || img.parentElement.parentElement;
        if (parent) parent.click();
      }
    });
    await w(3000);
    d.push('HAPVIDA');

    // === FORMULARIO ===
    // PME
    await page.evaluate(() => {
      const pme = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29'));
      if (pme) pme.click();
    });
    await w(2000);
    d.push('PME');

    // NOME
    await page.waitForSelector('#id-nomelead', { timeout: 15000 });
    const nInp = await page.$('#id-nomelead');
    if (nInp) { await nInp.click(); await nInp.type('teste', { delay: 20 }); }
    await w(1000);
    d.push('NOME');

    // AVANCAR 1
    const btns1 = await page.$$('button');
    for (const btn of btns1) {
      const info = await page.evaluate(el => { const s = getComputedStyle(el); return { t: el.textContent, d: s.display, v: s.visibility }; }, btn);
      if (info.t && info.t.includes('Avan') && info.d !== 'none' && info.v !== 'hidden') { await btn.click(); break; }
    }
    await w(3000);
    d.push('AV1');

    // CIDADE
    await page.waitForSelector('#cidade_nome', { timeout: 15000 });
    const cInp = await page.$('#cidade_nome');
    if (cInp) { await cInp.click(); await w(500); await cInp.type('teresina', { delay: 80 }); }
    await w(2000);

    const tc = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        if (el.textContent.trim() === 'Teresina - PI') {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (tc) await page.mouse.click(tc.x, tc.y);
    await w(2000);
    d.push('CIDADE');

    // MEI
    try { await page.select('select.Dropdown', '"mei___empres_rio_individual"'); } catch(e) {}
    await w(1500);
    d.push('MEI');

    // AVANCAR 2
    const btns2 = await page.$$('button');
    for (const btn of btns2) {
      const info = await page.evaluate(el => { const s = getComputedStyle(el); return { t: el.textContent, d: s.display, v: s.visibility }; }, btn);
      if (info.t && info.t.includes('Avan') && info.d !== 'none' && info.v !== 'hidden') { await btn.click(); break; }
    }
    await w(3000);
    d.push('AV2');

    // FAIXAS
    const fxCount = await page.evaluate(() => {
      let c = 0;
      document.querySelectorAll('input').forEach(inp => {
        const r = inp.getBoundingClientRect();
        const s = getComputedStyle(inp);
        if (r.width > 0 && s.display !== 'none' && !inp.id && inp.placeholder === '0' && inp.className.includes('cocys')) {
          inp.value = '1';
          inp.dispatchEvent(new Event('input', { bubbles: true }));
          inp.dispatchEvent(new Event('change', { bubbles: true }));
          c++;
        }
      });
      return c;
    });
    await w(2000);
    d.push('FX:' + fxCount);

    // AVANCAR 3
    const btns3 = await page.$$('button');
    for (const btn of btns3) {
      const info = await page.evaluate(el => { const s = getComputedStyle(el); return { t: el.textContent, d: s.display, v: s.visibility }; }, btn);
      if (info.t && info.t.includes('Avan') && info.d !== 'none' && info.v !== 'hidden') { await btn.click(); break; }
    }
    await w(4000);
    d.push('AV3');

    // ADD PRODUTOS
    const btns4 = await page.$$('button');
    for (const btn of btns4) {
      const info = await page.evaluate(el => { const s = getComputedStyle(el); return { t: el.textContent.trim(), d: s.display, v: s.visibility }; }, btn);
      if (info.t === 'Add Produtos' && info.d !== 'none' && info.v !== 'hidden') { await btn.click(); break; }
    }
    await w(3000);
    d.push('ADD');

    // HAPVIDA MODAL
    const hc = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        if (el.textContent.trim() === 'Hapvida') {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (hc) await page.mouse.click(hc.x, hc.y);
    await w(3000);
    d.push('HAP');

    // TABELA
    const tb = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        const t = el.textContent.trim();
        if (t.includes('Teresina') && t.includes('2') && t.includes('29')) {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (tb) await page.mouse.click(tb.x, tb.y);
    await w(2000);
    d.push('TAB');

    // AMBULATORIAL
    const ab = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        if (el.textContent.trim() === 'Ambulatorial') {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (ab) await page.mouse.click(ab.x, ab.y);
    await w(2000);
    d.push('AMB');

    // ACOMODACAO
    const ac = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        const t = el.textContent.trim().toLowerCase();
        if (t.includes('sem acomodação') && t.includes('coparticipação')) {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (ac) await page.mouse.click(ac.x, ac.y);
    await w(2000);
    d.push('ACO');

    // FECHA MODAL
    await page.mouse.click(1200, 400);
    await w(3000);
    d.push('FECHA');

    // EXTRAI VALORES
    const faixas = await page.evaluate(() => {
      const nomes = ['0 a 18 anos','19 a 23 anos','24 a 28 anos','29 a 33 anos','34 a 38 anos','39 a 43 anos','44 a 48 anos','49 a 53 anos','54 a 58 anos','59 anos ou mais'];
      const vals = [];
      const regex = /^\d{2,3}[,.]\d{2}$/;
      document.querySelectorAll('div, span').forEach(el => {
        const s = getComputedStyle(el);
        const r = el.getBoundingClientRect();
        if (s.display !== 'none' && r.width > 0 && el.textContent.length < 15) {
          const t = el.textContent.trim();
          if (regex.test(t) && !vals.some(v => v.text === t)) {
            vals.push({ text: t, y: r.y, x: r.x });
          }
        }
      });
      vals.sort((a, b) => a.y - b.y);
      return vals.slice(0, 10).map((v, i) => ({ faixa_etaria: nomes[i], valor: 'R$ ' + v.text.replace('.', ',') }));
    });
    d.push('V:' + faixas.length);

    return { success: true, debug: d.join('-'), faixas };
  } catch (error) {
    return { success: false, error: error.message, debug: d.join('-') };
  }
}"
}
